alter table public.profiles add column if not exists daily_credits integer not null default 80, add column if not exists paid_coins integer not null default 0, add column if not exists credits_refilled_at timestamptz not null default now(); update public.profiles set daily_credits=least(greatest(coalesce(credits,0),0),80), paid_coins=greatest(coalesce(credits,0)-80,0), credits_refilled_at=coalesce(credits_refilled_at,now()); alter table public.profiles add constraint profiles_daily_credits_nonnegative check (daily_credits>=0), add constraint profiles_paid_coins_nonnegative check (paid_coins>=0);